import{_ as a,o as n,c as t,ag as s}from"./chunks/framework.D1ek-kcM.js";const u=JSON.parse('{"title":"Command Line Usage","description":"","frontmatter":{},"headers":[],"relativePath":"CLI.md","filePath":"CLI.md"}'),o={name:"CLI.md"};function i(r,e,d,p,l,c){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="command-line-usage" tabindex="-1">Command Line Usage <a class="header-anchor" href="#command-line-usage" aria-label="Permalink to &quot;Command Line Usage&quot;">​</a></h1><p>The Dorpn compiler is a command line program named <code>dorpn</code>. You give it a <code>.dpn</code> source file, and it turns that file into something your computer can run. This page describes how to call the compiler, what each option does, and what files it produces.</p><p>By default Dorpn compiles to a native executable. It does this in steps: first it reads and checks your program, then it translates it to C code, and finally it hands that C code to the <code>clang</code> compiler together with the Dorpn runtime library. The result is a program that runs directly, with no interpreter involved. Dorpn can also translate your program to JavaScript instead, which is described further down.</p><hr><h2 id="basic-usage" tabindex="-1">Basic Usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic Usage&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>dorpn &lt;file.dpn&gt; [options]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The source file must be the <strong>first</strong> argument. Options come after it, and they can be combined in any order.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>dorpn hello.dpn                # compile only</span></span>
<span class="line"><span>dorpn hello.dpn --run          # compile and run immediately</span></span>
<span class="line"><span>dorpn hello.dpn -r -t          # compile, run, and show compile time</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>When you compile without <code>--run</code>, Dorpn prints where the executable was written and how to start it:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>✓ Generated C code: hello.c</span></span>
<span class="line"><span>✓ Compiled: hello</span></span>
<span class="line"><span>Run with: ./hello</span></span>
<span class="line"><span>Or: dorpn hello.dpn --run</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Calling <code>dorpn</code> with no arguments prints the help text.</p><hr><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Short</th><th>Long</th><th>Description</th></tr></thead><tbody><tr><td><code>-r</code></td><td><code>--run</code></td><td>Compile and run immediately</td></tr><tr><td><code>-k</code></td><td><code>--keep-c</code></td><td>Keep the generated C file</td></tr><tr><td><code>-V</code></td><td><code>--verbose</code></td><td>Show detailed compilation steps</td></tr><tr><td><code>-v</code></td><td><code>--version</code></td><td>Show version information</td></tr><tr><td><code>-h</code></td><td><code>--help</code></td><td>Show the help message</td></tr><tr><td><code>-ch</code></td><td><code>--cache</code></td><td>Clear the compiler cache</td></tr><tr><td><code>-t</code></td><td><code>--time</code></td><td>Show how long compilation took</td></tr><tr><td></td><td><code>--out &lt;path&gt;</code></td><td>Choose the output file</td></tr><tr><td><code>-js</code></td><td><code>--Javs</code></td><td>Compile to JavaScript instead of C</td></tr><tr><td></td><td><code>--upgrade</code></td><td>Upgrade Dorpn to the latest version</td></tr></tbody></table><p>If you pass an option that Dorpn does not know, it prints <code>Unknown option</code> together with a hint to use <code>--help</code>, and exits with code 1.</p><hr><h2 id="running-a-program" tabindex="-1">Running a Program <a class="header-anchor" href="#running-a-program" aria-label="Permalink to &quot;Running a Program&quot;">​</a></h2><p>The <code>--run</code> option compiles the program and starts it straight away. A separator line is printed first so you can tell compiler messages apart from your program&#39;s own output.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>$ dorpn hello.dpn --run</span></span>
<span class="line"><span>────────────────────────────────────────</span></span>
<span class="line"><span>Hello, Dorpn!</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>If your program ends with a non-zero exit code, for example through <code>error_out(2)</code> or <code>panic()</code>, Dorpn reports it after the program finishes:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>Program exited with code 2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><h2 id="keeping-the-c-file" tabindex="-1">Keeping the C File <a class="header-anchor" href="#keeping-the-c-file" aria-label="Permalink to &quot;Keeping the C File&quot;">​</a></h2><p>Normally the generated C file is deleted once the executable has been built. Pass <code>--keep-c</code> if you want to keep it, which is useful for inspecting exactly what Dorpn generated for your code.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>dorpn hello.dpn -k</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The C file is written next to your source file, with the same name and a <code>.c</code> extension. The <code>--verbose</code> option also keeps the C file.</p><hr><h2 id="choosing-the-output-path" tabindex="-1">Choosing the Output Path <a class="header-anchor" href="#choosing-the-output-path" aria-label="Permalink to &quot;Choosing the Output Path&quot;">​</a></h2><p>By default the executable is created next to the source file, with the same name and no extension. <code>hello.dpn</code> produces <code>hello</code>. Use <code>--out</code> to pick a different path:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>dorpn hello.dpn --out build/hello</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>--out</code> applies to the native executable. It does not change where JavaScript output is written.</p><hr><h2 id="compiling-to-javascript" tabindex="-1">Compiling to JavaScript <a class="header-anchor" href="#compiling-to-javascript" aria-label="Permalink to &quot;Compiling to JavaScript&quot;">​</a></h2><p>With <code>-js</code>, Dorpn translates your program to JavaScript instead of C. The <code>.js</code> file is written next to the source file, and no C compiler is needed.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>dorpn hello.dpn -js            # writes hello.js</span></span>
<span class="line"><span>dorpn hello.dpn -js -r         # writes hello.js and runs it with node</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Without <code>--run</code>, Dorpn tells you the command to start the program:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>✓ Generated Js code: hello.js</span></span>
<span class="line"><span>Run with: node hello.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Running the result requires <a href="https://nodejs.org" target="_blank" rel="noreferrer">Node.js</a> to be installed. Some built-in features rely on a small runtime file, <code>dorpn_runtime.js</code>, and the generated file loads it from the path it was given at compile time.</p><hr><h2 id="verbose-output" tabindex="-1">Verbose Output <a class="header-anchor" href="#verbose-output" aria-label="Permalink to &quot;Verbose Output&quot;">​</a></h2><p><code>--verbose</code> prints every stage of compilation: lexing, parsing, semantic analysis, C generation and the exact command used to call <code>clang</code>. It also shows the first tokens found in your file. This is mainly useful when you are debugging the compiler itself or a build that behaves unexpectedly.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>dorpn hello.dpn -V</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><h2 id="timing" tabindex="-1">Timing <a class="header-anchor" href="#timing" aria-label="Permalink to &quot;Timing&quot;">​</a></h2><p><code>--time</code> adds a final line that reports how long the whole compilation took:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>⏱ Compilation finished in 0.179 seconds.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><hr><h2 id="version-help-and-cache" tabindex="-1">Version, Help and Cache <a class="header-anchor" href="#version-help-and-cache" aria-label="Permalink to &quot;Version, Help and Cache&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>dorpn --version                # Dorpn Compiler v0.4.3</span></span>
<span class="line"><span>dorpn --help                   # list of all options</span></span>
<span class="line"><span>dorpn hello.dpn --cache        # remove the .dorpn_cache folder, if any</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>--version</code> and <code>--help</code> can be used without a source file. The <code>--cache</code> option deletes the <code>.dorpn_cache</code> folder in the current directory and then exits without compiling. If no such folder exists, it says so.</p><hr><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>dorpn --upgrade</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This checks the latest release on GitHub and compares it to the version you have installed. If a newer version exists, it downloads the Windows installer and runs it silently. If you are already on the newest version, it says so and exits. If the network is not reachable, it prints an error and the address of the releases page so you can download the update by hand.</p><hr><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>What must be available</th></tr></thead><tbody><tr><td>Native (default)</td><td>The <code>clang</code> compiler, and the Dorpn runtime files <code>dorpn_runtime.c</code> and <code>dorpn_runtime.h</code></td></tr><tr><td>JavaScript (<code>-js</code>)</td><td>Node.js, only if you use <code>--run</code></td></tr></tbody></table><p>Dorpn looks for the runtime files in this order and uses the first place where it finds both:</p><ol><li>The folder named by the <code>DORPN_RUNTIME_DIR</code> environment variable</li><li>A <code>runtime_lib</code> folder in the current directory</li><li>A <code>src</code> folder in the current directory</li><li>The current directory itself</li></ol><p>If none of them contains the runtime, the compiler stops with <code>Error: Dorpn runtime files not found!</code>.</p><p>If <code>DORPN_RUNTIME_DIR</code> is set, which is the case on Android, the executable is written to <code>/tmp</code> instead of next to the source file. Storage folders on Android are mounted in a way that does not allow programs to run from them, so a <code>/tmp</code> location is used to make the result runnable.</p><hr><h2 id="exit-codes" tabindex="-1">Exit Codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit Codes&quot;">​</a></h2><p>The compiler itself exits with code <code>0</code> on success and <code>1</code> on any failure, including a missing file, an unknown option, a syntax or semantic error, or a failed C build.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>$ dorpn missing.dpn</span></span>
<span class="line"><span>Error: File &#39;missing.dpn&#39; not found</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Errors in your own program are explained on the <a href="/Errors.html">Errors</a> page.</p>`,66)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
